import pandas as pd

class Solution:
    def maximum_transaction_each_day(self, transactions: pd.DataFrame) -> pd.DataFrame:
        df = transactions.copy()
        df["date"] = pd.to_datetime(df["day"]).dt.date
        rows = []
        for _, t in df.iterrows():
            same_day = df[df["date"] == t["date"]]
            if t["amount"] >= same_day["amount"].max():
                rows.append(int(t["transaction_id"]))
        return pd.DataFrame(sorted(rows), columns=["transaction_id"])

