#include <bits/stdc++.h>
using namespace std;

struct Txn { int id; string day; long long amount; };

static string dateOf(const string& ts) { return ts.substr(0, 10); }

class Solution {
public:
    vector<int> maximumTransactionEachDay(vector<Txn>& txns) {
        vector<int> res;
        for (auto& t : txns) {
            bool isMax = true;
            for (auto& o : txns)
                if (dateOf(o.day) == dateOf(t.day) && o.amount > t.amount) {
                    isMax = false;
                    break;
                }
            if (isMax) res.push_back(t.id);
        }
        sort(res.begin(), res.end());
        return res;
    }
};

