class Solution {
    static class Txn { int id; String day; long amount;
        Txn(int i, String d, long a) { id = i; day = d; amount = a; }
    }

    public List<Integer> maximumTransactionEachDay(List<Txn> txns) {
        List<Integer> res = new ArrayList<>();
        for (Txn t : txns) {
            boolean isMax = true;
            for (Txn o : txns)
                if (o.day.substring(0, 10).equals(t.day.substring(0, 10)) && o.amount > t.amount) {
                    isMax = false;
                    break;
                }
            if (isMax) res.add(t.id);
        }
        Collections.sort(res);
        return res;
    }
}

