import pandas as pd

class Solution:
    def maximum_transaction_each_day(self, transactions: pd.DataFrame) -> pd.DataFrame:
        df = transactions.copy()
        df["date"] = pd.to_datetime(df["day"]).dt.date
        best = df.groupby("date")["amount"].max().to_dict()
        winners = df[df["amount"] == df["date"].map(best)]
        ids = sorted(int(x) for x in winners["transaction_id"])
        return pd.DataFrame(ids, columns=["transaction_id"])

