struct Txn { int id; string day; long long amount; };

static string dateOf(const string& ts) { return ts.substr(0, 10); }

class Solution {
public:
    vector<int> maximumTransactionEachDay(vector<Txn>& txns) {
        unordered_map<string, long long> best;
        for (auto& t : txns)
            best[dateOf(t.day)] = max(best[dateOf(t.day)], t.amount);
        vector<int> res;
        for (auto& t : txns)
            if (t.amount == best[dateOf(t.day)]) res.push_back(t.id);
        sort(res.begin(), res.end());
        return res;
    }
};

