import java.util.*;

class Solution {
    static class Txn { int id; String day; long amount;
        Txn(int i, String d, long a) { id = i; day = d; amount = a; }
    }

    public List<Integer> maximumTransactionEachDay(List<Txn> txns) {
        Map<String, Long> best = new HashMap<>();
        for (Txn t : txns)
            best.merge(t.day.substring(0, 10), t.amount, Math::max);
        List<Integer> res = new ArrayList<>();
        for (Txn t : txns)
            if (t.amount == best.get(t.day.substring(0, 10))) res.add(t.id);
        Collections.sort(res);
        return res;
    }
}

