var maximumTransactionEachDay = function(txns) {
    const best = new Map();
    for (const t of txns) {
        const d = t.day.slice(0, 10);
        const cur = best.has(d) ? best.get(d) : -Infinity;
        best.set(d, Math.max(cur, t.amount));
    }
    return txns.filter(t => t.amount === best.get(t.day.slice(0, 10)))
               .map(t => t.transactionId)
               .sort((a, b) => a - b);
};
